import re

def reverse_vowels(s):
    vowels = re.findall(r'[aeiouAEIOU]', s)
    result = []
    index = 0
    for char in s:
        if re.match(r'[aeiouAEIOU]', char):
            result.append(vowels[-index - 1])
            index += 1
        else:
            result.append(char)
    return ''.join(result)
